pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address probed) public {
        vm.assume(probed != address(0));

        // Rule: the product's oracle getter always returns a real (non-zero)
        // oracle address — never the zero address — regardless of any input.
        IOracleProvider returned = c.oracle();

        assertTrue(
