// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    bytes32 constant ORACLE_SLOT = keccak256("equilibria.perennial.UPayoffProvider.oracle");

    function setUp() public { c = new C(); }

    function testFuzz_property(address storedOracle) public {
        // any non-zero address is admissible as the stored oracle address
        vm.assume(storedOracle != address(0));

        // place the fuzzed address in the oracle storage slot (public surface reads it back via oracle())
        bytes32 slot = keccak256(abi.encodePacked(ORACLE_SLOT));
        vm.store(address(c), slot, bytes32(uint256(uint160(storedOracle))));

        // the oracle getter must expose exactly the stored address, which is non-zero
        assertTrue(
            address(c.oracle()) != address(0) && address(c.oracle()) == storedOracle,
            "oracle() must return the stored non-zero oracle address"
        );
    }
}

