pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address oracleAddr;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 makerFee, uint256 takerFee) public {
        // keep fees in the admissible domain (<= 1.0 in 18 decimals)
        makerFee = bound(makerFee, 0, 1e18);
        takerFee = bound(takerFee, 0, 1e18);

        // oracle must be a contract address; deploy it (admissible environment)
        oracleAddr = address(new FakeOracle());

        // build ProductInfo calldata manually so only C needs importing:
        // (string,string,(uint8,uint8,bytes30),address,uint256,uint256,uint256,uint256,uint256,uint256,((int128,int128,int128,uint128)))
        bytes memory data = abi.encodeWithSignature(
            "initialize((string,string,(uint8,uint8,bytes30),address,uint256,uint256,uint256,uint256,uint256,uint256,((int128,int128,int128,uint128))))",
            "name",
            "symbol",
            (uint8(0), uint8(0), bytes30(0)),
            oracleAddr,
            uint256(1e18),   // maintenance
            uint256(0),      // fundingFee (admissible: <= 1e18)
            makerFee,
            takerFee,
            uint256(0),      // positionFee
            uint256(1e30),   // makerLimit
            (int128(0), int128(0), int128(0), uint128(0))
        );

        (bool initOk, ) = address(c).call(data);
        assertTrue(initOk, "initialization reverted");

        // GENERAL RULE: for every admissible initialization, c.oracle() returns
        // exactly the non-zero oracle address stored at initialization.
        assertTrue(address(c.oracle()) == oracleAddr, "oracle() must return the stored oracle");
    }
}

