pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, IProduct, PayoffDefinition, PayoffDefinitionLib, JumpRateUtilizationCurve, PackedFixed18, PackedUFixed18, UFixed18} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    OracleStub oracleStub;
    Initializer initializer;

    function setUp() public {
        c = new C();
        oracleStub = new OracleStub();
        initializer = new Initializer();
    }

    function testFuzz_property(uint256 feeSeed) public {
        // wide admissible domain: fees in [0, 1e18] (validated <= ONE), other params arbitrary
        UFixed18 fee = UFixed18.wrap(bound(feeSeed, 0, 1e18));
        UFixed18 zero = UFixed18.wrap(0);

        PayoffDefinition memory payoffDef = PayoffDefinition(
            PayoffDefinitionLib.PayoffType.Linear,
            PayoffDefinitionLib.PayoffDirection.Long,
            bytes30(0)
        );

        JumpRateUtilizationCurve memory curve = JumpRateUtilizationCurve({
            minRate: PackedFixed18.wrap(int128(0)),
            maxRate: PackedFixed18.wrap(int128(0)),
            targetRate: PackedFixed18.wrap(int128(0)),
            targetUtilization: PackedUFixed18.wrap(uint128(0))
        });

        IProduct.ProductInfo memory info = IProduct.ProductInfo({
            name: "T",
            symbol: "T",
            payoffDefinition: payoffDef,
            oracle: oracleStub,
            maintenance: zero,
            fundingFee: fee,
            makerFee: fee,
            takerFee: fee,
            positionFee: fee,
            makerLimit: UFixed18.wrap(type(uint256).max),
            utilizationCurve: curve
        });

        // initialization must go through a contract (isContract check on msg.sender)
        initializer.init(c, info);

        // General rule: after initialization, oracle() returns the exact non-zero
        // contract oracle address that was configured; never the zero address.
        assertTrue(
            address(c.oracle()) != address(0) && address(c.oracle()) == address(oracleStub),
            "oracle() must return the configured non-zero oracle"
        );
    }
}

