}

contract Initializer {
    function init(C c, IProduct.ProductInfo memory info) external {
        c.initialize(info);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Initializer ini;

    function setUp() public {
        c = new C();
        ini = new Initializer();
    }

    function testFuzz_property(uint8 t, uint8 d, bytes32 raw) public {
        uint8 payoffType = uint8(bound(t, 0, 1));
        uint8 direction = uint8(bound(d, 0, 1));
        bytes30 data = bytes30(raw);

        // Initialize c through a contract (initialize requires a code-bearing caller);
        // the helper itself serves as the (code-bearing) oracle address.
        ini.initializeProduct(address(c), address(ini), payoffType, direction, data);

        // General rule: the stored payoff definition is returned verbatim.
        PayoffDefinitionMirror memory got = ini.readPayoffDefinition(address(c));
        assertTrue(
            got.payoffType == payoffType && got.payoffDirection == direction && got.data == data,
            "payoffDefinition must round-trip the stored definition"
        );
    }
}

struct PayoffDefinitionMirror {
    uint8 payoffType;
    uint8 payoffDirection;
    bytes30 data;
}

struct CurveMirror {
    int128 minRate;
    int128 maxRate;
    int128 targetRate;
    int128 targetUtil1;
    uint128 targetUtil2;
}

struct ProductInfoMirror {
    string name;
    string symbol;
    PayoffDefinitionMirror payoffDefinition;
    address oracle;
    uint256 maintenance;
    uint256 fundingFee;
    uint256 makerFee;
    uint256 takerFee;
    uint256 positionFee;
    uint256 makerLimit;
    CurveMirror utilizationCurve;
}

contract Initializer {
    function initializeProduct(
        address c,
        address oracleAddr,
        uint8 payoffType,
        uint8 direction,
        bytes30 data
    ) external {
        ProductInfoMirror memory info;
        info.name = "T";
        info.symbol = "T";
        info.payoffDefinition = PayoffDefinitionMirror(payoffType, direction, data);
        info.oracle = oracleAddr;
        info.maintenance = 0;
        info.fundingFee = 0;
        info.makerFee = 0;
        info.takerFee = 0;
        info.positionFee = 0;
        info.makerLimit = 0;
        info.utilizationCurve = CurveMirror(0, 0, 0, 0, 0);

        (bool ok, ) = c.call(
            abi.encodeWithSelector(
                bytes4(keccak256("initialize((string,string,(uint8,uint8,bytes30),address,uint256,uint256,uint256,uint256,uint256,uint256,(int128,int128,int128,int128,uint128)))")),
                info
            )
        );
        require(ok, "initialize failed");
    }

    function readPayoffDefinition(address c) external view returns (PayoffDefinitionMirror memory) {
        (bool ok, bytes memory ret) = c.staticcall(
            abi.encodeWithSignature("payoffDefinition()")
        );
        require(ok, "payoffDefinition failed");
        return abi.decode(ret, (PayoffDefinitionMirror));
    }
}

