pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Harness harness;
    Dummy oracle;

    function setUp() public {
        c = new C();
        harness = new Harness();
        oracle = new Dummy();
    }

    function testFuzz_property(uint256 dataSeed, uint8 ptSeed, uint8 dirSeed) public {
        // Admissible domain: keep wide; data is arbitrary bytes30, enums kept in range.
        uint256 pt = bound(uint256(ptSeed), 0, 1);
        uint256 dir = bound(uint256(dirSeed), 0, 1);
        bytes30 data = bytes30(bytes32(dataSeed));

        PayoffDefinition memory def = PayoffDefinition({
            payoffType: PayoffDefinitionLib.PayoffType(pt),
            payoffDirection: PayoffDefinitionLib.PayoffDirection(dir),
            data: data
        });

        JumpRateUtilizationCurve memory curve = JumpRateUtilizationCurve({
            minRate: PackedFixed18.wrap(0),
            maxRate: PackedFixed18.wrap(0),
            targetRate: PackedFixed18.wrap(0),
            targetUtilization: PackedUFixed18.wrap(0)
        });

        IProduct.ProductInfo memory info = IProduct.ProductInfo({
            name: "T",
            symbol: "T",
            payoffDefinition: def,
            oracle: IOracleProvider(address(oracle)),
            maintenance: UFixed18.wrap(0),
            fundingFee: UFixed18.wrap(0),
            makerFee: UFixed18.wrap(0),
            takerFee: UFixed18.wrap(0),
            positionFee: UFixed18.wrap(0),
            makerLimit: UFixed18.wrap(0),
            utilizationCurve: curve
        });

        harness.initializeProduct(address(c), info);

        PayoffDefinition memory stored = c.payoffDefinition();
        assertTrue(
            stored.data == data,
            "payoffDefinition must return the initialized data payload"
        );
    }
}

contract Harness {
    function initializeProduct(address product, IProduct.ProductInfo memory info) external {
        C(product).initialize(info);
    }
}

